 void ensureRoom(){if(fixture||!foreground)return;if(!forum.isEmpty()){load(false);if(!historyUser.isEmpty())return;connect();ui.removeCallbacks(heartbeat);ui.post(heartbeat);return;}if(resolving)return;if(credential("LOGIN_ID").isEmpty()){state.setText("请在“我的”登录后返回聊天室");return;}resolving=true;state.setText("正在恢复聊天室…");task(()->{Map<String,String> p=new LinkedHashMap<>();p.put("page","1");JSONObject r=api("/v1/forum/followForumList",p);if(!"success".equals(r.optString("status")))throw new ServiceError(r.optString("message","无法获取聊天室，点击右上角重试"));return r;},r->{String found=chooseForum(r.optJSONArray("data"));if(found.isEmpty())throw new ServiceError("暂未找到已加入的聊天室，请检查圈子权限后重试");forum=found;ChatHome.rememberForum(this,forum);model.user=credential("LOGIN_ID");draftKey="draft."+model.user+"."+forum;input.setText(getPreferences(0).getString(draftKey,""));input.setEnabled(true);send.setEnabled(true);ensureRoom();},()->resolving=false);}
 static String chooseForum(JSONArray list){if(list==null)return "";String single="";int count=0;for(int i=0;i<list.length();i++){JSONObject item=list.optJSONObject(i);if(item==null)continue;String id=item.optString("forum_id");if(!id.matches("[1-9][0-9]*"))continue;if("价值投研小圈".equals(item.optString("forum_name")))return id;single=id;count++;}return count==1?single:"";}
