 private void disconnect(){ui.removeCallbacks(heartbeat);ui.removeCallbacks(reconnect);connecting=false;if(socket!=null){socket.close();socket=null;}}
 private interface Work{JSONObject run()throws Exception;}
 private interface Done{void run(JSONObject data)throws Exception;}
 private void task(Work work,Done done,Runnable finallyDo){task(work,done,finallyDo,false);}
 private void task(Work work,Done done,Runnable finallyDo,boolean settle){int turn=generation;network.execute(()->{JSONObject result=null;Exception error=null;try{result=work.run();}catch(Exception e){error=e;}final JSONObject r=result;final Exception err=error;ui.post(()->{if(isDestroyed())return;if(!settle&&(turn!=generation||!foreground))return;finallyDo.run();try{if(err!=null)throw err;done.run(r);}catch(Exception e){state.setText(e instanceof ServiceError?e.getMessage():"连接失败，点右上角重试");}});});}
 private JSONObject api(String path,Map<String,String> params)throws Exception{return api(path,params,false);}
 private JSONObject api(String path,Map<String,String> params,boolean get)throws Exception{
  String token=credential("access_token");if(token.isEmpty())throw new ServiceError("请先在“我的”登录");
  LinkedHashMap<String,String> values=new LinkedHashMap<>();values.put("source","android");values.put("appversion","1.3.0");values.put("user_id",credential("LOGIN_ID"));
  try{String url=(String)Class.forName("pc6").getMethod("d",String.class).invoke(null,"https://mapp.zx017.net/chattingRoom/"+forum);Uri u=Uri.parse(url);for(String k:new String[]{"channel_code","device_id","source","appversion","user_id"}){String v=u.getQueryParameter(k);if(v!=null)values.put(k,v);}}catch(Exception ignored){}
  values.putAll(params);if(!get)values.put("Authorization","Bearer "+token);StringBuilder form=new StringBuilder();for(Map.Entry<String,String> e:values.entrySet()){if(form.length()>0)form.append('&');form.append(URLEncoder.encode(e.getKey(),"UTF-8")).append('=').append(URLEncoder.encode(e.getValue(),"UTF-8"));}
  HttpURLConnection c=(HttpURLConnection)new URL("https://api.zx017.net"+path+(get?"?"+form:"")).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestMethod(get?"GET":"POST");c.setDoOutput(!get);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded; charset=UTF-8");c.setRequestProperty("Authorization","Bearer "+token);
  try{byte[] body=form.toString().getBytes("UTF-8");if(!get){c.setFixedLengthStreamingMode(body.length);try(OutputStream out=c.getOutputStream()){out.write(body);}}int code=c.getResponseCode();if(code==401||code==403)throw new ServiceError("登录已失效或无权访问，请返回“我的”检查");if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream()){return new JSONObject(new String(read(in,8*1024*1024),"UTF-8"));}}finally{c.disconnect();}
 }
 static byte[] read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("response too large");out.write(b,0,n);}return out.toByteArray();}
 private Map<String,String> args(){Map<String,String> p=new LinkedHashMap<>();p.put("forum_id",forum);return p;}
 private static class ServiceError extends IOException{ServiceError(String s){super(s);}}
 private static void check(JSONObject r)throws ServiceError{if(r.optInt("code",-1)!=1)throw new ServiceError(r.optString("message","服务暂时不可用"));}
