 private void changeFilter(int mode){if(mode==1)onlyMaster=!onlyMaster;else{if(filterMode==mode)return;filterMode=mode;onlyMaster=false;}loadVersion++;loading=false;before=0;hasOlder=true;userScrolling=false;pendingEvents.clear();paintFilters();model.messages.clear();refresh();load(false);}
 private void maybeLoadOlder(){if(list!=null&&userScrolling&&hasOlder&&before>0&&!loading&&list.getFirstVisiblePosition()==0&&list.getChildCount()>0&&list.getChildAt(0).getTop()>=list.getPaddingTop())load(true);}
 private Map<String,String> chatParams(int mode,boolean leaders,long cursor,JSONObject circle){Map<String,String> p=args();p.put("limit","20");if(historyUser.isEmpty())p.put("is_show_admin_history",leaders?"1":"0");else p.put("chat_user_id",historyUser);if(mode==2){p.put("view_type","3");if(circle.optInt("chat_room_style")!=1){p.put("limit_time","1724817600");p.put("chat_room_style","0");}}if(cursor>0)p.put("before_id",Long.toString(cursor));return p;}
 private void load(boolean older){load(older,false);}
 private void load(boolean older,boolean sync){if(loading||fixture||forum.isEmpty()||(older&&!hasOlder))return;loading=true;final int version=++loadVersion,mode=filterMode;final boolean leaders=onlyMaster;pendingEvents.clear();if(older)state.setText("正在加载更早消息…");final long cursor=older?before:0;final int first=list.getFirstVisiblePosition();final long anchor=first>=0&&first<rows.size()?rows.get(first).optLong("Id"):0;final int offset=list.getChildCount()>0?list.getChildAt(0).getTop():0;final int oldSize=rows.size();final boolean bottom=rows.isEmpty()||list.getLastVisiblePosition()>=rows.size()-2;
  task(()->{JSONObject permissions=api("/v1/forum/forumInfo",args());if(!"success".equals(permissions.optString("status")))throw new ServiceError(permissions.optString("message","无法读取圈子权限"));Map<String,String> p=chatParams(mode,leaders,cursor,permissions.getJSONObject("data"));JSONObject r=api(mode==2?"/goapi/room/get_new_chat_list":"/goapi/room/get_chat_list",p);check(r);r.put("circle",permissions.getJSONObject("data"));return r;},r->{if(version!=loadVersion)return;int keepFirst=sync?list.getFirstVisiblePosition():first;long keepId=sync&&keepFirst>=0&&keepFirst<rows.size()?rows.get(keepFirst).optLong("Id"):anchor;int keepOffset=sync&&list.getChildCount()>0?list.getChildAt(0).getTop():offset;boolean follow=sync?(rows.isEmpty()||list.getLastVisiblePosition()>=rows.size()-2):bottom;JSONArray batch=r.optJSONArray("data");mergeHistory(r,!older&&!sync,mode);if(!sync){if(batch!=null&&batch.length()>0){long min=Long.MAX_VALUE;for(int i=0;i<batch.length();i++)min=Math.min(min,batch.getJSONObject(i).optLong("Id"));hasOlder=!older||min<cursor;before=min;}else hasOlder=false;}refresh();state.setText(historyUser.isEmpty()?(socket!=null&&socket.isOpen()?"● 实时连接":"正在连接…"):(rows.isEmpty()?"暂无可查看的历史发言":"当前圈子的发言 · 点消息可回复"));if(older)list.setSelectionFromTop(Math.max(0,first+rows.size()-oldSize),offset);else if(follow)bottom();else if(sync){for(int i=0;i<rows.size();i++)if(rows.get(i).optLong("Id")==keepId){list.setSelectionFromTop(i,keepOffset);break;}if(rows.size()>oldSize)newMessages.setVisibility(View.VISIBLE);}},()->{if(version==loadVersion)loading=false;});
 }
 private void mergeHistory(JSONObject response,boolean replace,int mode)throws JSONException {model.permissions(response.getJSONObject("circle"));if(replace)model.messages.clear();model.merge(response.optJSONArray("data"));if(mode!=2&&historyUser.isEmpty())model.merge(response.optJSONArray("user_view_self_chat"));for(JSONObject event:pendingEvents)applyEvent(event);pendingEvents.clear();}
 private void refresh(){heading.setText(historyUser.isEmpty()?model.circle.optString("name","价值投研小圈"):historyName+"的发言");rows.clear();for(JSONObject m:model.visibleMessages())if(!onlyMaster||model.isLeader(m))rows.add(m);adapter.notifyDataSetChanged();boolean muted=!model.admin&&model.circle.optInt("chat_banned_to_post")==1;input.setHint(muted?"全体禁言中":"说点什么…");input.setEnabled(!muted);send.setEnabled(!muted&&!sending);send.setAlpha(muted||sending?.45f:1f);}
 private void bottom(){if(newMessages!=null)newMessages.setVisibility(View.GONE);list.post(()->list.setSelection(Math.max(0,rows.size()-1)));}
