 private void loadImage(ImageView v,String url){Bitmap b=bitmaps.get(url);if(b!=null){v.setImageBitmap(b);return;}images.execute(()->{try{URL u=new URL(url);if(!"https".equals(u.getProtocol())&&!"http".equals(u.getProtocol()))throw new IOException("invalid image URL");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);byte[] bytes;try(InputStream in=c.getInputStream()){bytes=read(in,12*1024*1024);}finally{c.disconnect();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1400||options.outHeight/options.inSampleSize>1800)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap decoded=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(decoded==null)throw new IOException("invalid image");if(decoded!=null){bitmaps.put(url,decoded);ui.post(()->{if(!isDestroyed()&&url.equals(v.getTag()))v.setImageBitmap(decoded);});}}catch(Exception ignored){ui.post(()->{if(!isDestroyed()&&url.equals(v.getTag())){v.setImageResource(android.R.drawable.ic_dialog_alert);v.setContentDescription("图片加载失败，点击全屏重试");}});}});}
